import { memo } from "react";

function MIcon({
  name,
  size = 24,
  fill = false,
  className,
  style,
  "aria-hidden": ariaHidden = true,
}: {
  name: string;
  size?: number;
  fill?: boolean;
  className?: string;
  style?: React.CSSProperties;
  "aria-hidden"?: boolean;
}) {
  const map = fill ? FILLED : OUTLINED;
  const icon = map[name] ?? OUTLINED[name];
  if (!icon) {
    // An unknown name renders nothing at all — silently, which let typos survive for
    // months. Shout about it in dev, stay quiet in production.
    if (process.env.NODE_ENV !== "production") {
      console.warn('[MIcon] Ikona "' + name + '" neni v registru — nevykresli se nic. Doplnte ji do MIcon.tsx.');
    }
    return null;
  }
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox={icon.viewBox}
      width={size}
      height={size}
      fill="currentColor"
      className={className}
      style={style}
      aria-hidden={ariaHidden}
      focusable="false"
    >
      {icon.d.map((d, i) => <path key={i} d={d} />)}
    </svg>
  );
}

